// Generates src/styles/tokens.css and src/tokens/tokens.ts from tokens/tokens.json.
// tokens.json is the single source of truth. Run `npm run tokens` after editing it,
// or `npm run tokens:check` in CI to fail when the generated files are stale.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(resolve(root, 'tokens/tokens.json'), 'utf8'));
const check = process.argv.includes('--check');

const cssVars = [];
const darkVars = [];
const lightVars = [];
const flat = {};
const flatDark = {};
// A token may carry a `dark` value; it overrides the variable under [data-theme="dark"].
const add = (name, value, dark) => {
  cssVars.push(`  --${name}: ${value};`);
  flat[name] = value;
  if (dark !== undefined) {
    darkVars.push(`  --${name}: ${dark};`);
    lightVars.push(`  --${name}: ${value};`);
    flatDark[name] = dark;
  }
};
// Keys such as '3.75' become '3_75' (every dot is replaced) so they are valid CSS custom property names.
const key = (k) => k.replace(/\./g, '_');

for (const [group, entries] of Object.entries(tokens.color))
  for (const [name, t] of Object.entries(entries)) add(`color-${group}-${name}`, t.value, t.dark);
for (const [name, t] of Object.entries(tokens.font.family)) add(`font-${name}`, t.value);
for (const [name, t] of Object.entries(tokens.font.weight)) add(`font-weight-${name}`, t.value);
for (const [name, t] of Object.entries(tokens.typography)) {
  add(`text-${name}-size`, t.size);
  add(`text-${name}-line-height`, t.lineHeight);
  add(`text-${name}-weight`, t.weight);
  if (t.letterSpacing) add(`text-${name}-letter-spacing`, t.letterSpacing);
}
for (const [name, t] of Object.entries(tokens.space)) add(`space-${key(name)}`, t.value);
for (const [name, t] of Object.entries(tokens.radius)) add(`radius-${key(name)}`, t.value);
for (const [name, t] of Object.entries(tokens.shadow)) add(`shadow-${name}`, t.value, t.dark);
for (const [name, t] of Object.entries(tokens.gradient)) add(`gradient-${name}`, t.value, t.dark);
for (const [name, t] of Object.entries(tokens.size)) add(`size-${name}`, t.value);
for (const [name, t] of Object.entries(tokens.motion)) add(`motion-${name}`, t.value);
for (const [name, t] of Object.entries(tokens.letterSpacing)) add(`tracking-${key(name)}`, t.value);
for (const [name, t] of Object.entries(tokens.lineHeight)) add(`leading-${key(name)}`, t.value);
for (const [name, t] of Object.entries(tokens.borderWidth)) add(`border-width-${key(name)}`, t.value);
for (const [name, t] of Object.entries(tokens.strokeWidth)) add(`stroke-width-${key(name)}`, t.value);

const header = '/* Generated by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit by hand. */\n';
// Light is the default. Dark applies to any subtree under [data-theme="dark"] or .dark (usually <html>);
// [data-theme="light"] / .light resets the themed variables, so a light section can sit inside a dark page.
const css =
  `${header}:root {\n  color-scheme: light;\n${cssVars.join('\n')}\n}\n\n` +
  `[data-theme='dark'],\n.dark {\n  color-scheme: dark;\n${darkVars.join('\n')}\n}\n\n` +
  `[data-theme='light'],\n.light {\n  color-scheme: light;\n${lightVars.join('\n')}\n}\n`;
const ts = `${header}export const tokens = ${JSON.stringify(tokens, null, 2)} as const;\n\nexport const cssVariables = ${JSON.stringify(flat, null, 2)} as const;\n\n/** Values that change under [data-theme="dark"]; every other variable keeps its light value. */\nexport const cssVariablesDark = ${JSON.stringify(flatDark, null, 2)} as const;\n\nexport type CssVariable = keyof typeof cssVariables;\n`;

const outputs = [
  [resolve(root, 'src/styles/tokens.css'), css],
  [resolve(root, 'src/tokens/tokens.ts'), ts],
];

let stale = false;
for (const [file, content] of outputs) {
  if (check) {
    let current = '';
    try { current = readFileSync(file, 'utf8'); } catch {}
    if (current !== content) { console.error(`Stale: ${file}. Run npm run tokens.`); stale = true; }
  } else {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, content);
    console.log(`Wrote ${file.replace(root + '/', '')}`);
  }
}
if (stale) process.exit(1);
